function freshStore() {
  return {
    version: 1,
    attempts: {},
    active: {},
    lastResults: {},
    enrollments: [],
    stats: {
      answered: 0,
      correct: 0,
      sessions: 0,
      activityByDate: {},
      studyDates: []
    },
    settings: {
      dailyGoal: 10
    }
  };
}

function loadStore() {
  const base = freshStore();
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return base;
    const saved = JSON.parse(raw);
    return {
      ...base,
      ...saved,
      attempts: saved.attempts || {},
      active: saved.active || {},
      lastResults: saved.lastResults || {},
      enrollments: Array.isArray(saved.enrollments) ? saved.enrollments : [],
      stats: { ...base.stats, ...(saved.stats || {}) },
      settings: { ...base.settings, ...(saved.settings || {}) }
    };
  } catch (error) {
    return base;
  }
}

function loadSession() {
  try {
    const raw = localStorage.getItem(SESSION_KEY);
    if (!raw) return null;
    const saved = JSON.parse(raw);
    return saved && typeof saved.email === "string" ? saved : null;
  } catch (error) {
    return null;
  }
}

