function saveStore() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(store));
  } catch (error) {
    // Progress still works for the current session if storage is unavailable.
  }
  updateSidebarStreak();
}

function saveSession(user) {
  currentUser = user;
  try {
    if (user) {
      localStorage.setItem(SESSION_KEY, JSON.stringify(user));
    } else {
      localStorage.removeItem(SESSION_KEY);
    }
  } catch (error) {
    // The signed-in state still works for the current session.
  }
  applyUser();
}

function initialsFor(name) {
  const parts = String(name || "Guest").trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return "GS";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase();
}

function firstNameFor(name) {
  return String(name || "there").trim().split(/\s+/)[0] || "there";
}

function applyUser() {
  const name = currentUser?.name || "Alex Morgan";
  const role = currentUser?.role || "CFA Level I candidate";
  const initials = currentUser ? initialsFor(currentUser.name) : "AM";
  const nameTarget = document.getElementById("sidebarUserName");
  const roleTarget = document.getElementById("sidebarUserRole");
  const sidebarAvatar = document.getElementById("sidebarAvatar");
  const topbarAvatar = document.getElementById("topbarAvatar");
  if (nameTarget) nameTarget.textContent = name;
  if (roleTarget) roleTarget.textContent = role;
  if (sidebarAvatar) sidebarAvatar.textContent = initials;
  if (topbarAvatar) {
    topbarAvatar.textContent = initials;
    topbarAvatar.setAttribute("aria-label", name);
  }
}

function isEnrolled(courseId) {
  return (store.enrollments || []).includes(courseId);
}

function planById(planId) {
  return PLAN_OPTIONS.find((plan) => plan.id === planId) || PLAN_OPTIONS[2];
}

function planPrice(course, planId) {
  const annual = COURSE_PRICING[course.id] || 199;
  if (planId === "monthly") return Math.round(annual * 0.11);
  if (planId === "quarterly") return Math.round(annual * 0.29);
  return annual;
}

function planSavings(course, planId) {
  const monthly = planPrice(course, "monthly");
  const plan = planById(planId);
  return Math.max(0, monthly * plan.months - planPrice(course, planId));
}

function estimateStudyHours(course) {
  const questions = courseStats(course).totalQuestions;
  return Math.max(2, Math.round((questions * 1.8) / 5) * 5);
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (char) => {
    const map = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" };
    return map[char];
  });
}

function icon(name, extraClass = "") {
  return `<svg class="icon ${extraClass}" aria-hidden="true"><use href="#i-${name}"></use></svg>`;
}

function pad(value) {
  return String(value).padStart(2, "0");
}

function dateKey(date = new Date()) {
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

function formatTimer(totalSeconds) {
  const seconds = Math.max(0, Math.floor(totalSeconds));
  return `${pad(Math.floor(seconds / 60))}:${pad(seconds % 60)}`;
}

function formatShortDate(iso) {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return "";
  return new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" }).format(date);
}

function formatLongDate(date = new Date()) {
  return new Intl.DateTimeFormat("en-US", {
    weekday: "long",
    month: "long",
    day: "numeric"
  }).format(date);
}

function greeting() {
  const hour = new Date().getHours();
  if (hour < 12) return "Good morning";
  if (hour < 18) return "Good afternoon";
  return "Good evening";
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function entryFor(sectionId) {
  return CATALOG.find((entry) => entry.section.id === sectionId);
}

function courseFor(courseId) {
  return COURSES.find((course) => course.id === courseId);
}

function categoryFor(course, categoryId) {
  return course.categories.find((category) => category.id === categoryId);
}

function sectionAttempt(sectionId) {
  return store.attempts[sectionId];
}

function isComplete(sectionId) {
  return Boolean(store.attempts[sectionId] && store.attempts[sectionId].completed);
}

function activeSession(sectionId) {
  return store.active[sectionId];
}

function courseStats(course) {
  const sections = course.categories.flatMap((category) => category.sections);
  const doneSections = sections.filter((section) => isComplete(section.id)).length;
  const totalQuestions = sections.reduce((sum, section) => sum + section.questions.length, 0);
  return {
    totalSections: sections.length,
    doneSections,
    totalQuestions,
    percent: sections.length ? Math.round((doneSections / sections.length) * 100) : 0
  };
}

function overallStats() {
  const totalSections = CATALOG.length;
  const doneSections = CATALOG.filter((entry) => isComplete(entry.section.id)).length;
  return {
    totalSections,
    doneSections,
    percent: totalSections ? Math.round((doneSections / totalSections) * 100) : 0
  };
}

function computeStreak() {
  const dates = new Set(store.stats.studyDates || []);
  const cursor = new Date();
  if (!dates.has(dateKey(cursor))) {
    cursor.setDate(cursor.getDate() - 1);
  }
  let streak = 0;
  while (dates.has(dateKey(cursor))) {
    streak += 1;
    cursor.setDate(cursor.getDate() - 1);
  }
  return streak;
}

function answeredToday() {
  return store.stats.activityByDate[dateKey()] || 0;
}

function accuracy() {
  if (!store.stats.answered) return 0;
  return Math.round((store.stats.correct / store.stats.answered) * 100);
}

function updateSidebarStreak() {
  const target = document.getElementById("sidebarStreak");
  if (target) target.textContent = computeStreak();
}

function recordAnswer(wasCorrect) {
  store.stats.answered += 1;
  if (wasCorrect) store.stats.correct += 1;
  const key = dateKey();
  store.stats.activityByDate[key] = (store.stats.activityByDate[key] || 0) + 1;
  if (!store.stats.studyDates.includes(key)) store.stats.studyDates.push(key);
}

function ringMarkup(percent, ringClass, centerClass, label) {
  const value = clamp(Math.round(percent), 0, 100);
  const circumference = 2 * Math.PI * 52;
  const offset = circumference * (1 - value / 100);
  return `
    <div class="${ringClass}">
      <svg viewBox="0 0 120 120" aria-hidden="true">
        <circle class="ring-bg" cx="60" cy="60" r="52"></circle>
        <circle class="ring-value" cx="60" cy="60" r="52" stroke-dasharray="${circumference.toFixed(2)}" stroke-dashoffset="${offset.toFixed(2)}"></circle>
      </svg>
      <div class="${centerClass}">
        <strong>${value}%</strong>
        <span>${escapeHtml(label)}</span>
      </div>
    </div>
  `;
}

function goalRingMarkup(done, goal) {
  const ratio = goal ? clamp(done / goal, 0, 1) : 0;
  const circumference = 2 * Math.PI * 30;
  const offset = circumference * (1 - ratio);
  return `
    <div class="goal-ring">
      <svg viewBox="0 0 72 72" aria-hidden="true">
        <circle class="ring-bg" cx="36" cy="36" r="30"></circle>
        <circle class="ring-value" cx="36" cy="36" r="30" stroke-dasharray="${circumference.toFixed(2)}" stroke-dashoffset="${offset.toFixed(2)}"></circle>
      </svg>
      <div class="goal-ring-text">
        ${done}<small>of ${goal}</small>
      </div>
    </div>
  `;
}

function lastSevenDays() {
  const days = [];
  for (let index = 6; index >= 0; index -= 1) {
    const date = new Date();
    date.setHours(12, 0, 0, 0);
    date.setDate(date.getDate() - index);
    const key = dateKey(date);
    days.push({
      key,
      label: new Intl.DateTimeFormat("en-US", { weekday: "narrow" }).format(date),
      fullLabel: new Intl.DateTimeFormat("en-US", { weekday: "long" }).format(date),
      value: store.stats.activityByDate[key] || 0,
      isToday: index === 0
    });
  }
  return days;
}

function pickRecommendation() {
  const activeEntries = Object.values(store.active)
    .filter((session) => entryFor(session.sectionId))
    .sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0));
  if (activeEntries.length) {
    return { entry: entryFor(activeEntries[0].sectionId), isActive: true };
  }
  const nextFresh = CATALOG.find((entry) => !isComplete(entry.section.id));
  return { entry: nextFresh || CATALOG[0], isActive: false };
}

function firstSectionForCourse(course) {
  const active = Object.values(store.active)
    .filter((session) => entryFor(session.sectionId)?.course.id === course.id)
    .sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0))[0];
  if (active) return entryFor(active.sectionId);
  return (
    CATALOG.find((entry) => entry.course.id === course.id && !isComplete(entry.section.id)) ||
    CATALOG.find((entry) => entry.course.id === course.id)
  );
}

function nextSectionAfter(sectionId) {
  const startIndex = CATALOG.findIndex((entry) => entry.section.id === sectionId);
  if (startIndex === -1) return null;
  for (let index = startIndex + 1; index < CATALOG.length; index += 1) {
    if (!isComplete(CATALOG[index].section.id)) return CATALOG[index];
  }
  for (let index = 0; index < CATALOG.length; index += 1) {
    if (index !== startIndex) return CATALOG[index];
  }
  return null;
}

function showToast(message) {
  if (!toastEl) return;
  toastEl.innerHTML = `${icon("check")}<span>${escapeHtml(message)}</span>`;
  toastEl.classList.add("show");
  window.clearTimeout(toastTimer);
  toastTimer = window.setTimeout(() => toastEl.classList.remove("show"), 3000);
}

function setDocumentTitle(title) {
  document.title = `${title} — LoS Site`;
}

function updateTopbar(title) {
  const titleEl = document.getElementById("topbarTitle");
  if (titleEl) titleEl.textContent = title;
  setDocumentTitle(title);
}

function updateNav(routeName) {
  document.querySelectorAll(".nav-link").forEach((link) => {
    const name = link.dataset.nav;
    const active =
      name === routeName ||
      (routeName === "course" && name === "courses") ||
      (routeName === "results" && name === "progress");
    link.classList.toggle("active", active);
  });
}

/* ---------- Routing ---------- */
function parseRoute() {
  const raw = window.location.hash.replace(/^#\/?/, "");
  return raw.split("/").filter(Boolean);
}

function stopTimer() {
  if (timerInterval) {
    window.clearInterval(timerInterval);
    timerInterval = null;
  }
}

function persistActive() {
  if (!practice) return;
  practice.active.updatedAt = Date.now();
  store.active[practice.entry.section.id] = practice.active;
  saveStore();
}

function renderRoute(options = {}) {
  const shouldScroll = options.scroll !== false;
  if (practice) persistActive();
  stopTimer();
  practice = null;
  document.body.classList.remove("is-paused", "sidebar-open");
  closeSearch();

  const parts = parseRoute();
  const routeName = parts[0] || "dashboard";
  let content = "";
  let isPractice = false;

  if (routeName === "practice" && parts[1]) {
    isPractice = true;
    document.body.classList.remove("public-mode");
    document.body.classList.add("practice-mode");
    updateNav("");
    updateTopbar("Practice session");
    content = renderPractice(parts[1]);
    app.innerHTML = content;
    startTimerLoop();
  } else if (["home", "login", "signup", "subscribe", "plan"].includes(routeName)) {
    document.body.classList.remove("practice-mode");
    document.body.classList.add("public-mode");
    let title = "Home";
    let pageHtml = "";

    if (routeName === "login" || routeName === "signup") {
      title = routeName === "login" ? "Sign in" : "Create account";
      pageHtml = renderAuthPage(routeName);
    } else if (routeName === "subscribe") {
      title = "Plans & access";
      pageHtml = renderSubscribePage();
    } else if (routeName === "plan") {
      const course = courseFor(parts[1]);
      if (course) {
        title = `${course.name} plan`;
        pageHtml = renderPlanPage(course);
      } else {
        title = "Plan not found";
        pageHtml = marketingShell(
          "subscribe",
          `<main class="plan-page"><section class="panel empty-state"><div class="empty-icon">${icon("info")}</div><strong>We could not find that course plan</strong><p>Return to plans and choose one of the available exam tracks.</p><a class="btn btn-primary" href="#/subscribe">View plans</a></section></main>`
        );
      }
    } else {
      pageHtml = renderHomePage();
    }

    updateNav("");
    updateTopbar(title);
    app.innerHTML = pageHtml;
  } else {
    document.body.classList.remove("practice-mode", "public-mode");
    let title = "Dashboard";
    let pageHtml = "";

    if (routeName === "courses") {
      title = "Course library";
      pageHtml = renderCoursesPage();
    } else if (routeName === "course" && parts[1]) {
      const course = courseFor(parts[1]);
      if (course) {
        if (parts[2]) {
          const category = categoryFor(course, parts[2]);
          if (category) {
            title = category.name;
            pageHtml = renderCategoryPage(course, category);
          } else {
            title = "Main section not found";
            pageHtml = renderNotFound();
          }
        } else {
          title = course.name;
          pageHtml = renderCoursePage(course);
        }
      } else {
        title = "Course not found";
        pageHtml = renderNotFound();
      }
    } else if (routeName === "progress") {
      title = "My progress";
      pageHtml = renderProgressPage();
    } else if (routeName === "results" && parts[1]) {
      title = "Session results";
      pageHtml = renderResultsPage(parts[1]);
    } else {
      title = "Dashboard";
      pageHtml = renderDashboard();
    }

    updateNav(routeName);
    updateTopbar(title);
    app.innerHTML = pageHtml;
  }

  if (shouldScroll) window.scrollTo({ top: 0, behavior: "auto" });
}

function navigateTo(hash) {
  if (window.location.hash === hash) {
    renderRoute();
  } else {
    window.location.hash = hash;
  }
}

function openSection(sectionId) {
  if (!entryFor(sectionId)) return;
  navigateTo(`#/practice/${sectionId}`);
}

function retakeSection(sectionId) {
  delete store.active[sectionId];
  saveStore();
  navigateTo(`#/practice/${sectionId}`);
}

/* ---------- Dashboard ---------- */
function courseCardMarkup(course) {
  const stats = courseStats(course);
  return `
    <a class="course-card" href="#/course/${course.id}" style="--accent:${course.accent};--tint:${course.tint}">
      <div class="course-top">
        <span class="course-mark">${escapeHtml(course.short)}</span>
        <span class="course-arrow">${icon("arrow-right")}</span>
      </div>
      <div class="course-copy">
        <h3>${escapeHtml(course.name)}</h3>
        <p>${escapeHtml(course.level)} · ${stats.totalSections} sections</p>
      </div>
      <div class="course-footer">
        <div class="course-progress-label">
          <span>${stats.doneSections} of ${stats.totalSections} complete</span>
          <strong>${stats.percent}%</strong>
        </div>
        <div class="progress-track"><div class="progress-fill" style="width:${stats.percent}%"></div></div>
      </div>
    </a>
  `;
}

function continueCardMarkup() {
  const { entry, isActive } = pickRecommendation();
  if (!entry) return "";
  const { course, category, section } = entry;
  const session = store.active[section.id];
  const answered = session ? Object.keys(session.answers || {}).length : 0;
  const total = section.questions.length;
  const percent = isActive && total ? Math.round((answered / total) * 100) : courseStats(course).percent;
  const label = isActive
    ? `Question ${Math.min((session?.index || 0) + 1, total)} of ${total}`
    : `${courseStats(course).doneSections} of ${courseStats(course).totalSections} sections complete`;

  return `
    <article class="continue-card">
      <div class="continue-inner">
        <div class="continue-kicker">
          ${icon(isActive ? "play" : "sparkles")}
          ${isActive ? "Session in progress" : "Recommended next"}
        </div>
        <h3>${escapeHtml(section.name)}</h3>
        <p class="continue-meta">${escapeHtml(course.short)} · ${escapeHtml(category.name)}</p>
        <div class="continue-progress">
          <div class="progress-track"><div class="progress-fill" style="width:${percent}%"></div></div>
          <div class="continue-progress-label">
            <span>${label}</span>
            <span>${percent}%</span>
          </div>
        </div>
        <a class="btn" href="#/practice/${section.id}">
          ${icon(isActive ? "play" : "arrow-right")}
          ${isActive ? "Resume session" : "Start session"}
        </a>
      </div>
    </article>
  `;
}

function weekPanelMarkup() {
  const days = lastSevenDays();
  const max = Math.max(...days.map((day) => day.value), 10);
  const weekTotal = days.reduce((sum, day) => sum + day.value, 0);

  return `
    <section class="panel week-panel">
      <div class="section-head" style="margin-bottom:0">
        <div>
          <h2>This week</h2>
          <p>${weekTotal ? `${weekTotal} questions answered over the last seven days.` : "Your activity will appear here after your first question."}</p>
        </div>
        <span class="badge">${icon("trend")} ${weekTotal} answered</span>
      </div>
      <div class="week-chart" aria-label="Questions answered over the last seven days">
        ${days
          .map((day) => {
            const height = day.value ? Math.max(8, Math.round((day.value / max) * 100)) : 4;
            return `
              <div class="day-col" title="${escapeHtml(day.fullLabel)}: ${day.value} questions">
                <span class="day-value">${day.value || ""}</span>
                <div class="day-bar-wrap">
                  <div class="day-bar ${day.value ? "has-value" : ""} ${day.isToday ? "today" : ""}" style="height:${height}%"></div>
                </div>
                <span class="day-label ${day.isToday ? "today" : ""}">${escapeHtml(day.label)}</span>
              </div>
            `;
          })
          .join("")}
      </div>
    </section>
  `;
}

function renderDashboard() {
  const overall = overallStats();
  const goal = store.settings.dailyGoal || 10;
  const today = answeredToday();

  return `
    <div class="page view-enter">
      <div class="page-heading">
        <div>
          <p class="eyebrow">${formatLongDate()}</p>
          <h1>${greeting()}, <em>Alex.</em></h1>
          <p>A focused ten-minute session is the fastest way to make today count. Pick up a course or jump straight into a practice set.</p>
        </div>
        <div class="page-heading-actions">
          <button class="btn btn-primary" id="headingQuickPractice">
            ${icon("sparkles")} Quick practice
          </button>
        </div>
      </div>

      <div class="stats-grid">
        <article class="stat-card featured">
          <span class="stat-icon">${icon("flame")}</span>
          <div class="stat-body">
            <div class="stat-value">${computeStreak()}<small>days</small></div>
            <div class="stat-label">Current study streak</div>
          </div>
        </article>
        <article class="stat-card">
          <span class="stat-icon">${icon("check")}</span>
          <div class="stat-body">
            <div class="stat-value">${store.stats.answered}<small>questions</small></div>
            <div class="stat-label">Answered all time</div>
          </div>
        </article>
        <article class="stat-card">
          <span class="stat-icon">${icon("target")}</span>
          <div class="stat-body">
            <div class="stat-value">${accuracy()}<small>%</small></div>
            <div class="stat-label">Overall accuracy</div>
          </div>
        </article>
        <article class="stat-card">
          <span class="stat-icon">${icon("trophy")}</span>
          <div class="stat-body">
            <div class="stat-value">${overall.doneSections}<small>/ ${overall.totalSections}</small></div>
            <div class="stat-label">Sections completed</div>
          </div>
        </article>
      </div>

      <div class="dash-grid">
        <section class="panel">
          <div class="section-head">
            <div>
              <h2>Your courses</h2>
              <p>Four exam tracks, one focused workspace.</p>
            </div>
            <a class="text-link" href="#/courses">View library ${icon("arrow-right")}</a>
          </div>
          <div class="course-grid">
            ${COURSES.slice(0, 4).map(courseCardMarkup).join("")}
          </div>
        </section>

        <aside class="side-stack">
          ${continueCardMarkup()}
          <article class="goal-card">
            ${goalRingMarkup(today, goal)}
            <div class="goal-copy">
              <strong>${today >= goal ? "Today's goal is complete" : "Today's practice goal"}</strong>
              <p>${today >= goal ? "Nice work. Keep the streak alive with a quick review, or stop while you are ahead." : `You have answered ${today} of ${goal} questions today. A short session is enough to build momentum.`}</p>
            </div>
          </article>
          ${accessCardMarkup()}
        </aside>
      </div>

      ${weekPanelMarkup()}
    </div>
  `;
}

/* ---------- Course library ---------- */
function renderCoursesPage() {
  const filters = ["All", "Investments", "Accounting", "Risk"];
  const visible = courseFilter === "all" ? COURSES : COURSES.filter((course) => course.group === courseFilter);

  return `
    <div class="page view-enter">
      <div class="page-heading">
        <div>
          <p class="eyebrow">Course library</p>
          <h1>Choose your <em>next edge.</em></h1>
          <p>Structured practice sets for the exams that move your career forward. Every section includes explanations and saved progress.</p>
        </div>
        <div class="page-heading-actions">
          <button class="btn btn-primary" id="headingQuickPractice">
            ${icon("sparkles")} Quick practice
          </button>
        </div>
      </div>

      <div class="library-toolbar">
        <div class="filter-chips" role="group" aria-label="Filter courses">
          ${filters
            .map((filter) => {
              const value = filter === "All" ? "all" : filter;
              return `<button class="filter-chip ${courseFilter === value ? "active" : ""}" data-filter="${value}">${filter}</button>`;
            })
            .join("")}
        </div>
        <span class="badge">${COURSES.reduce((sum, course) => sum + courseStats(course).totalQuestions, 0)} practice questions</span>
      </div>

      <div class="library-grid">
        ${visible
          .map((course) => {
            const stats = courseStats(course);
            return `
              <article class="library-card" style="--accent:${course.accent};--tint:${course.tint}">
                <div class="library-visual">
                  <strong>${escapeHtml(course.short)}</strong>
                  <span>${escapeHtml(course.level)}</span>
                </div>
                <div class="library-body">
                  <h3>${escapeHtml(course.name)}</h3>
                  <p>${escapeHtml(course.description)}</p>
                  <div class="library-meta">
                    <span class="badge">${escapeHtml(course.field)}</span>
                    <span class="badge">${stats.totalSections} sections</span>
                    <span class="badge">${stats.totalQuestions} questions</span>
                  </div>
                  <div class="library-progress">
                    <div class="library-progress-top">
                      <span>${stats.doneSections} of ${stats.totalSections} complete</span>
                      <strong>${stats.percent}%</strong>
                    </div>
                    <div class="progress-track"><div class="progress-fill" style="width:${stats.percent}%"></div></div>
                  </div>
                </div>
                <a class="library-cta" href="#/course/${course.id}" aria-label="Open ${escapeHtml(course.name)}">${icon("arrow-right")}</a>
              </article>
            `;
          })
          .join("")}
      </div>
    </div>
  `;
}

/* ---------- Course detail ---------- */
function renderCoursePage(course) {
  const stats = courseStats(course);
  const recommended = firstSectionForCourse(course);
  const active = recommended ? store.active[recommended.section.id] : null;
  const isDone = recommended ? isComplete(recommended.section.id) : false;
  const ctaLabel = active ? "Resume course" : isDone ? "Retake a section" : "Start course";
  const ctaHash = recommended ? `#/practice/${recommended.section.id}` : "#/courses";

  return `
    <div class="page view-enter">
      <div class="breadcrumb">
        <a href="#/courses">Course library</a>
        ${icon("chevron")}
        <span>${escapeHtml(course.name)}</span>
      </div>

      <section class="course-hero" style="--accent:${course.accent};--tint:${course.tint}">
        <div class="course-hero-copy">
          <div class="course-eyebrow">${escapeHtml(course.field)} · ${escapeHtml(course.level)}</div>
          <h1>${escapeHtml(course.name)}</h1>
          <p>${escapeHtml(course.description)}</p>
          <div class="course-meta">
            <span class="course-chip">${icon("layers")} ${course.categories.length} main sections</span>
            <span class="course-chip">${icon("book")} ${stats.totalSections} subsections</span>
            <span class="course-chip">${icon("clock")} ${stats.totalQuestions} questions</span>
          </div>
        </div>
        <div class="course-progress-card">
          <div class="progress-ring-wrap">
            ${ringMarkup(stats.percent, "progress-ring", "ring-center", "complete")}
          </div>
          <div class="course-progress-copy">
            <strong>${stats.doneSections} of ${stats.totalSections} subsections complete</strong>
            <span>${stats.percent ? "Keep going. Your progress is saved automatically." : "Begin with any section that fits your study plan."}</span>
          </div>
          <a class="btn btn-primary btn-wide" href="${ctaHash}">
            ${icon(active ? "play" : "arrow-right")} ${ctaLabel}
          </a>
        </div>
      </section>

      <section class="panel curriculum">
        <div class="section-head">
          <div>
            <h2>Main sections</h2>
            <p>Open a main section to see its subsections, ordered by LOS number.</p>
          </div>
          <span class="badge">${course.categories.length} sections</span>
        </div>

        <div class="main-section-grid">
          ${course.categories
            .map((category) => {
              const categorySections = category.sections;
              const categoryDone = categorySections.filter((section) => isComplete(section.id)).length;
              const categoryPercent = Math.round((categoryDone / categorySections.length) * 100);
              const questionCount = categorySections.reduce((sum, section) => sum + section.questions.length, 0);
              const losNumbers = categorySections.map((section) => section.los).filter((los) => Number.isFinite(los));
              const losLabel = losNumbers.length
                ? `LOS ${Math.min(...losNumbers)}–${Math.max(...losNumbers)}`
                : "";
              return `
                <a class="main-section-card" href="#/course/${course.id}/${category.id}">
                  <span class="category-icon">${icon(category.icon)}</span>
                  <span class="main-section-body">
                    <strong>${escapeHtml(category.name)}</strong>
                    <span class="main-section-counts">${categorySections.length} subsections · ${questionCount} questions${losLabel ? ` · ${losLabel}` : ""}</span>
                    <span class="main-section-blurb">${escapeHtml(category.blurb)}</span>
                    <span class="main-section-progress">
                      <span class="progress-track"><span class="progress-fill green" style="width:${categoryPercent}%"></span></span>
                      <span>${categoryDone}/${categorySections.length} complete</span>
                    </span>
                  </span>
                  <span class="course-arrow">${icon("chevron")}</span>
                </a>
              `;
            })
            .join("")}
        </div>
      </section>
    </div>
  `;
}

function sortedCategorySections(category) {
  return [...category.sections].sort((a, b) => {
    const aLos = Number.isFinite(a.los) ? a.los : Number.MAX_SAFE_INTEGER;
    const bLos = Number.isFinite(b.los) ? b.los : Number.MAX_SAFE_INTEGER;
    return aLos - bLos || a.name.localeCompare(b.name);
  });
}

function renderCategoryPage(course, category) {
  const sections = sortedCategorySections(category);
  const doneSections = sections.filter((section) => isComplete(section.id)).length;
  const percent = sections.length ? Math.round((doneSections / sections.length) * 100) : 0;
  const totalQuestions = sections.reduce((sum, section) => sum + section.questions.length, 0);
  const losNumbers = sections.map((section) => section.los).filter((los) => Number.isFinite(los));
  const losLabel = losNumbers.length
    ? `LOS ${Math.min(...losNumbers)}–${Math.max(...losNumbers)}`
    : "";

  return `
    <div class="page view-enter">
      <div class="breadcrumb">
        <a href="#/courses">Course library</a>
        ${icon("chevron")}
        <a href="#/course/${course.id}">${escapeHtml(course.name)}</a>
        ${icon("chevron")}
        <span>${escapeHtml(category.name)}</span>
      </div>

      <section class="course-hero" style="--accent:${course.accent};--tint:${course.tint}">
        <div class="course-hero-copy">
          <div class="course-eyebrow">Main section</div>
          <h1>${escapeHtml(category.name)}</h1>
          <p>${escapeHtml(category.blurb)}</p>
          <div class="course-meta">
            <span class="course-chip">${icon("layers")} ${sections.length} subsections</span>
            <span class="course-chip">${icon("book")} ${totalQuestions} questions</span>
            ${losLabel ? `<span class="course-chip">${icon("target")} ${losLabel}</span>` : ""}
          </div>
        </div>
        <div class="course-progress-card">
          <div class="progress-ring-wrap">
            ${ringMarkup(percent, "progress-ring", "ring-center", "complete")}
          </div>
          <div class="course-progress-copy">
            <strong>${doneSections} of ${sections.length} subsections complete</strong>
            <span>Subsections are ordered by LOS number.</span>
          </div>
          <a class="btn btn-primary btn-wide" href="#/course/${course.id}">
            ${icon("arrow-left")} All main sections
          </a>
        </div>
      </section>

      <section class="panel curriculum">
        <div class="section-head">
          <div>
            <h2>Subsections</h2>
            <p>Work through each subsection in LOS order, then retake it any time.</p>
          </div>
          <span class="badge">${percent}% complete</span>
        </div>

        <div class="section-list section-list--flush">
          ${sections
            .map((section) => {
              const attempt = sectionAttempt(section.id);
              const session = activeSession(section.id);
              const done = Boolean(attempt && attempt.completed);
              const statusClass = session ? "in-progress" : done ? "done" : "";
              const statusIcon = done ? "check" : session ? "play" : "chevron";
              const actionLabel = done ? "Retake" : session ? "Resume" : "Start";
              const actionAttr = done
                ? `data-retake="${section.id}"`
                : `data-open-section="${section.id}"`;
              const losText = Number.isFinite(section.los) ? `LOS ${section.los} · ` : "";
              return `
                <div class="section-row">
                  <div class="section-main">
                    <span class="section-status ${statusClass}">${icon(statusIcon)}</span>
                    <div class="section-copy">
                      <strong>${escapeHtml(section.name)}</strong>
                      <span>${losText}${section.questions.length} questions · ${session ? "In progress" : done ? "Completed" : "Not started"}</span>
                    </div>
                  </div>
                  <span class="section-score">${done ? `Best <strong>${attempt.bestScore || 0}/${section.questions.length}</strong>` : ""}</span>
                  <button class="section-action" ${actionAttr}>${actionLabel}</button>
                </div>
              `;
            })
            .join("")}
        </div>
      </section>
    </div>
  `;
}

/* ---------- Progress ---------- */
function historyEntries() {
  const entries = [];
  Object.entries(store.attempts).forEach(([sectionId, attempt]) => {
    const entry = entryFor(sectionId);
    if (!entry) return;
    (attempt.history || []).forEach((item) => {
      entries.push({ entry, item });
    });
  });
  return entries.sort((a, b) => new Date(b.item.date) - new Date(a.item.date));
}

function renderProgressPage() {
  const overall = overallStats();
  const history = historyEntries().slice(0, 7);

  return `
    <div class="page view-enter">
      <div class="page-heading">
        <div>
          <p class="eyebrow">My progress</p>
          <h1>Evidence of the <em>work.</em></h1>
          <p>Every completed section and every retake is saved here, so you can see the direction you are moving.</p>
        </div>
      </div>

      <section class="progress-hero">
        ${ringMarkup(overall.percent, "big-ring", "big-ring-center", "complete")}
        <div class="progress-hero-copy">
          <h2>${overall.doneSections ? `${overall.doneSections} ${overall.doneSections === 1 ? "section" : "sections"} down, more to master.` : "Your first completed section starts here."}</h2>
          <p>${overall.doneSections ? "Progress is built one focused session at a time. Review a completed section whenever you want a sharper recall." : "Choose a course, work through a practice set, and your scores will be tracked automatically."}</p>
          <div class="progress-stats">
            <div class="mini-stat"><strong>${store.stats.answered}</strong><span>Answered</span></div>
            <div class="mini-stat"><strong>${accuracy()}%</strong><span>Accuracy</span></div>
            <div class="mini-stat"><strong>${computeStreak()}</strong><span>Day streak</span></div>
            <div class="mini-stat"><strong>${store.stats.sessions}</strong><span>Sessions</span></div>
          </div>
        </div>
      </section>

      <div class="progress-layout">
        <section class="panel">
          <div class="section-head">
            <div>
              <h2>Course progress</h2>
              <p>A section counts toward progress when you finish its final question.</p>
            </div>
          </div>
          <div class="course-progress-list">
            ${COURSES.map((course) => {
              const stats = courseStats(course);
              return `
                <a class="course-progress-item" href="#/course/${course.id}">
                  <span class="mini-mark" style="background:${course.accent}">${escapeHtml(course.short)}</span>
                  <div class="course-progress-item-copy">
                    <div class="course-progress-item-top">
                      <strong>${escapeHtml(course.name)}</strong>
                      <span>${stats.doneSections}/${stats.totalSections} · ${stats.percent}%</span>
                    </div>
                    <div class="progress-track"><div class="progress-fill green" style="width:${stats.percent}%"></div></div>
                  </div>
                  <span class="section-status ${stats.doneSections ? "done" : ""}">${icon(stats.doneSections ? "check" : "chevron")}</span>
                </a>
              `;
            }).join("")}
          </div>
        </section>

        <section class="panel">
          <div class="section-head">
            <div>
              <h2>Recent sessions</h2>
              <p>Your latest completed practice sets.</p>
            </div>
          </div>
          ${
            history.length
              ? `<div class="history-list">
                  ${history
                    .map(({ entry, item }) => `
                      <div class="history-item">
                        <span class="history-icon">${icon("trophy")}</span>
                        <div class="history-copy">
                          <strong>${escapeHtml(entry.section.name)}</strong>
                          <span>${escapeHtml(entry.course.short)} · ${formatShortDate(item.date)} · ${formatTimer(item.time)}</span>
                        </div>
                        <div class="history-score">
                          <strong>${item.score}/${item.total}</strong>
                          <span>${Math.round((item.score / item.total) * 100)}%</span>
                        </div>
                      </div>
                    `)
                    .join("")}
                </div>`
              : `<div class="empty-state">
                  <div class="empty-icon">${icon("chart")}</div>
                  <strong>No completed sessions yet</strong>
                  <p>Finish a practice section and your score, time, and accuracy will appear here.</p>
                  <button class="btn btn-primary btn-sm" data-open-section="${CATALOG[0].section.id}">Start first section</button>
                </div>`
          }
        </section>
      </div>
    </div>
  `;
}

/* ---------- Practice ---------- */
function renderPractice(sectionId) {
  const entry = entryFor(sectionId);
  if (!entry) {
    document.body.classList.remove("practice-mode");
    return `<div class="page view-enter">${renderNotFoundInternal()}</div>`;
  }

  let active = store.active[sectionId];
  if (!active) {
    active = {
      sectionId,
      index: 0,
      answers: {},
      elapsed: 0,
      paused: false,
      startedAt: Date.now(),
      updatedAt: Date.now()
    };
    store.active[sectionId] = active;
    saveStore();
  }

  if (active.index >= entry.section.questions.length) {
    active.index = entry.section.questions.length - 1;
  }

  practice = { entry, active };
  document.body.classList.toggle("is-paused", Boolean(active.paused));
  return practiceMarkup(entry, active);
}

function practiceMarkup(entry, active) {
  const { course, category, section } = entry;
  const questions = section.questions;
  const questionIndex = active.index;
  const question = questions[questionIndex];
  const selected = active.answers[questionIndex];
  const answered = selected !== undefined && selected !== null;
  const isCorrect = answered && selected === question.answer;
  const total = questions.length;
  const answeredCount = Object.keys(active.answers).length;
  const correctCount = questions.reduce(
    (sum, item, index) => sum + (active.answers[index] === item.answer ? 1 : 0),
    0
  );
  const progress = Math.round(((questionIndex + (answered ? 1 : 0)) / total) * 100);
  const tip = TIPS[questionIndex % TIPS.length];
  const timerToggleLabel = active.paused ? "Resume timer" : "Pause timer";

  return `
    <div class="practice-shell view-enter">
      <header class="practice-top">
        <div class="practice-top-left">
          <a class="icon-btn" href="#/course/${course.id}" aria-label="Exit practice">${icon("arrow-left")}</a>
          <div class="practice-crumb">
            <strong>${escapeHtml(course.short)}</strong>
            ${icon("chevron")}
            <span>${escapeHtml(category.name)}</span>
            ${icon("chevron")}
            <strong>${escapeHtml(section.name)}</strong>
          </div>
        </div>
        <div class="practice-top-right">
          <div class="timer-pill ${active.paused ? "paused" : ""}" id="timerPill">
            ${icon("clock")}
            <span class="timer-value" id="timerValue">${formatTimer(active.elapsed)}</span>
            <button class="timer-toggle" id="timerToggle" aria-label="${timerToggleLabel}">
              ${icon(active.paused ? "play" : "pause")}
            </button>
          </div>
          <a class="btn btn-ghost btn-sm" href="#/course/${course.id}">${icon("exit")} Exit</a>
        </div>
      </header>

      <div class="practice-progress-head">
        <span>Question <strong>${questionIndex + 1}</strong> of ${total}</span>
        <span>${answeredCount} answered · ${correctCount} correct</span>
      </div>
      <div class="practice-progress-track">
        <div class="practice-progress-fill" style="width:${progress}%"></div>
      </div>

      <div class="practice-stage">
        <section class="question-card">
          <div class="question-meta">
            <span class="q-count">Question ${pad(questionIndex + 1)}</span>
            <span class="q-difficulty">${escapeHtml(question.difficulty)}</span>
            <span class="q-topic">${escapeHtml(question.topic)}</span>
          </div>
          <h1>${escapeHtml(question.prompt)}</h1>
          <p class="question-hint">Choose one answer. You can pause the timer at any time.</p>

          <div class="options" role="group" aria-label="Answer choices">
            ${question.options
              .map((option, index) => {
                let classes = "option";
                let indicator = "";
                if (answered) {
                  classes += " is-locked";
                  if (index === question.answer) {
                    classes += " is-correct";
                    indicator = icon("check");
                  } else if (index === selected) {
                    classes += " is-wrong";
                    indicator = icon("x");
                  } else {
                    classes += " is-muted";
                  }
                }
                return `
                  <button class="${classes}" data-option="${index}" ${answered ? "aria-disabled=\"true\"" : ""}>
                    <span class="option-letter">${String.fromCharCode(65 + index)}</span>
                    <span class="option-text">${escapeHtml(option)}</span>
                    <span class="option-indicator">${indicator}</span>
                  </button>
                `;
              })
              .join("")}
          </div>

          ${
            answered
              ? `<div class="feedback ${isCorrect ? "correct" : "incorrect"}">
                  <div class="feedback-head">
                    <span class="feedback-icon">${icon(isCorrect ? "check" : "x")}</span>
                    <strong>${isCorrect ? "Correct." : "Not quite."}</strong>
                  </div>
                  <p>${escapeHtml(question.explanation)}</p>
                  <div class="feedback-answer">
                    Correct choice: <strong>${String.fromCharCode(65 + question.answer)}. ${escapeHtml(question.options[question.answer])}</strong>
                  </div>
                </div>`
              : ""
          }

          <div class="question-footer">
            <div class="footer-note">
              ${icon(answered ? "lightbulb" : "info")}
              <span>${answered ? "Read the explanation before moving on. It is stored with this session." : "Select the best answer to reveal the explanation."}</span>
            </div>
            <button class="btn btn-primary" id="nextBtn" ${answered ? "" : "disabled"}>
              ${answered && questionIndex === total - 1 ? "Finish section" : "Next question"}
              ${icon(answered && questionIndex === total - 1 ? "check" : "arrow-right")}
            </button>
          </div>
        </section>

        <aside class="practice-aside">
          <section class="session-card">
            <div class="session-card-head">
              <h3>Session map</h3>
              <span>${total} questions</span>
            </div>
            <div class="q-dots">
              ${questions
                .map((item, index) => {
                  const answer = active.answers[index];
                  let status = "";
                  if (answer !== undefined && answer !== null) {
                    status = answer === item.answer ? "correct" : "wrong";
                  }
                  if (index === questionIndex) status += " current";
                  return `<span class="q-dot ${status}">${index + 1}</span>`;
                })
                .join("")}
            </div>
            <div class="session-summary">
              <div><span>Answered</span><strong>${answeredCount} / ${total}</strong></div>
              <div><span>Remaining</span><strong>${total - answeredCount}</strong></div>
              <div><span>Correct</span><strong>${correctCount}</strong></div>
              <div><span>Timer</span><strong>${active.paused ? "Paused" : "Running"}</strong></div>
            </div>
          </section>

          <section class="tip-card">
            <div class="tip-label">${icon("lightbulb")} Study note</div>
            <p>${escapeHtml(tip)}</p>
          </section>
        </aside>

        <div class="pause-overlay" id="pauseOverlay" ${active.paused ? "" : "hidden"}>
          <div class="pause-box">
            <div class="pause-icon">${icon("pause")}</div>
            <h3>Session paused</h3>
            <p>Your timer is stopped and answers are locked. Resume when you are ready to continue.</p>
            <button class="btn btn-primary btn-lg" id="resumePause">${icon("play")} Resume session</button>
          </div>
        </div>
      </div>
    </div>
  `;
}

function refreshPractice(options = {}) {
  if (!practice) return;
  stopTimer();
  const { entry, active } = practice;
  app.innerHTML = practiceMarkup(entry, active);
  startTimerLoop();
  if (options.scroll) {
    window.scrollTo({ top: 0, behavior: "smooth" });
  }
}

function startTimerLoop() {
  stopTimer();
  if (!practice) return;
  timerInterval = window.setInterval(() => {
    if (!practice || practice.active.paused) return;
    practice.active.elapsed += 1;
    const timerValue = document.getElementById("timerValue");
    if (timerValue) timerValue.textContent = formatTimer(practice.active.elapsed);
    if (practice.active.elapsed % 10 === 0) {
      practice.active.updatedAt = Date.now();
      store.active[practice.entry.section.id] = practice.active;
      saveStore();
    }
  }, 1000);
}

function togglePause() {
  if (!practice) return;
  practice.active.paused = !practice.active.paused;
  persistActive();
  const paused = practice.active.paused;
  document.body.classList.toggle("is-paused", paused);
  const pill = document.getElementById("timerPill");
  const toggle = document.getElementById("timerToggle");
  const overlay = document.getElementById("pauseOverlay");
  if (pill) pill.classList.toggle("paused", paused);
  if (toggle) {
    toggle.innerHTML = icon(paused ? "play" : "pause");
    toggle.setAttribute("aria-label", paused ? "Resume timer" : "Pause timer");
  }
  if (overlay) overlay.hidden = !paused;
  if (!paused) {
    const resume = document.getElementById("resumePause");
    if (resume) resume.blur();
  }
}

function answerQuestion(optionIndex) {
  if (!practice || practice.active.paused) return;
  const { active, entry } = practice;
  const questionIndex = active.index;
  const question = entry.section.questions[questionIndex];
  if (active.answers[questionIndex] !== undefined && active.answers[questionIndex] !== null) return;
  const correct = optionIndex === question.answer;
  active.answers[questionIndex] = optionIndex;
  active.updatedAt = Date.now();
  recordAnswer(correct);
  store.active[entry.section.id] = active;
  saveStore();
  refreshPractice();
}

function nextQuestion() {
  if (!practice) return;
  const { active, entry } = practice;
  const currentAnswer = active.answers[active.index];
  if (currentAnswer === undefined || currentAnswer === null) return;
  if (active.index >= entry.section.questions.length - 1) {
    finishSection(entry);
    return;
  }
  active.index += 1;
  active.updatedAt = Date.now();
  store.active[entry.section.id] = active;
  saveStore();
  refreshPractice({ scroll: true });
}

function finishSection(entry) {
  const active = store.active[entry.section.id] || practice?.active;
  if (!active) return;
  const questions = entry.section.questions;
  const total = questions.length;
  const score = questions.reduce(
    (sum, question, index) => sum + (active.answers[index] === question.answer ? 1 : 0),
    0
  );
  const completedAt = new Date().toISOString();
  const previous = store.attempts[entry.section.id] || { history: [] };
  const history = Array.isArray(previous.history) ? previous.history : [];
  history.push({ score, total, time: active.elapsed, date: completedAt });

  store.attempts[entry.section.id] = {
    completed: true,
    total,
    bestScore: Math.max(previous.bestScore || 0, score),
    lastScore: score,
    attempts: (previous.attempts || 0) + 1,
    lastTime: active.elapsed,
    completedAt,
    history
  };

  store.lastResults[entry.section.id] = {
    answers: { ...active.answers },
    elapsed: active.elapsed,
    score,
    total,
    date: completedAt
  };

  store.stats.sessions += 1;
  delete store.active[entry.section.id];
  practice = null;
  stopTimer();
  document.body.classList.remove("is-paused");
  saveStore();
  showToast("Section complete. Your progress has been saved.");
  navigateTo(`#/results/${entry.section.id}`);
}

/* ---------- Results ---------- */
function renderResultsPage(sectionId) {
  const entry = entryFor(sectionId);
  if (!entry) return `<div class="page view-enter">${renderNotFoundInternal()}</div>`;
  const { course, category, section } = entry;
  const result = store.lastResults[sectionId];
  const attempt = store.attempts[sectionId];

  if (!result || !attempt) {
    return `
      <div class="results-shell view-enter">
        <div class="breadcrumb">
          <a href="#/course/${course.id}">${escapeHtml(course.short)}</a>
          ${icon("chevron")}
          <span>${escapeHtml(section.name)}</span>
        </div>
        <section class="panel empty-state">
          <div class="empty-icon">${icon("info")}</div>
          <strong>No session to review yet</strong>
          <p>Complete all questions in this section to see your score, timing, and explanations.</p>
          <a class="btn btn-primary" href="#/practice/${section.id}">${icon("play")} Start section</a>
        </section>
      </div>
    `;
  }

  const percent = Math.round((result.score / result.total) * 100);
  const title = percent >= 85 ? "A sharp result." : percent >= 60 ? "Solid work." : "A useful baseline.";
  const next = nextSectionAfter(section.id);

  return `
    <div class="results-shell view-enter">
      <div class="breadcrumb">
        <a href="#/course/${course.id}">${escapeHtml(course.short)}</a>
        ${icon("chevron")}
        <a href="#/course/${course.id}">${escapeHtml(category.name)}</a>
        ${icon("chevron")}
        <span>${escapeHtml(section.name)}</span>
      </div>

      <section class="result-summary">
        ${ringMarkup(percent, "result-ring", "result-ring-center", "score")}
        <div class="result-copy">
          <span class="result-badge">${icon("check")} Section complete</span>
          <h1>${title}</h1>
          <p>You answered ${result.score} of ${result.total} questions correctly. Review the explanations below, then retake the section whenever you want a sharper recall.</p>
          <div class="result-stats">
            <div class="result-stat"><strong>${result.score}/${result.total}</strong><span>Correct</span></div>
            <div class="result-stat"><strong>${percent}%</strong><span>Accuracy</span></div>
            <div class="result-stat"><strong>${formatTimer(result.elapsed)}</strong><span>Time taken</span></div>
            <div class="result-stat"><strong>${attempt.bestScore}/${result.total}</strong><span>Best score</span></div>
          </div>
          <div class="result-actions">
            <button class="btn btn-primary" data-retake="${section.id}">${icon("rotate")} Retake section</button>
            <a class="btn btn-soft" href="#/course/${course.id}">${icon("arrow-left")} Back to course</a>
            ${
              next
                ? `<button class="btn btn-soft" data-open-section="${next.section.id}">${icon("arrow-right")} Next section</button>`
                : ""
            }
          </div>
        </div>
      </section>

      <section class="panel review-panel">
        <div class="section-head">
          <div>
            <h2>Review the reasoning</h2>
            <p>Open any question to revisit the correct answer and explanation.</p>
          </div>
          <span class="badge">${result.total} questions</span>
        </div>
        <div class="review-list">
          ${section.questions
            .map((question, index) => {
              const selected = result.answers[index];
              const correct = selected === question.answer;
              const selectedText =
                selected !== undefined && selected !== null ? question.options[selected] : "No answer recorded";
              return `
                <details class="review-item">
                  <summary>
                    <span class="review-status ${correct ? "correct" : "wrong"}">${icon(correct ? "check" : "x")}</span>
                    <span class="review-q">${index + 1}. ${escapeHtml(question.prompt)}</span>
                    <span class="review-expand">Review</span>
                  </summary>
                  <div class="review-body">
                    <p><strong>Correct answer:</strong> ${String.fromCharCode(65 + question.answer)}. ${escapeHtml(question.options[question.answer])}</p>
                    ${correct ? "" : `<p><strong>Your answer:</strong> ${escapeHtml(selectedText)}</p>`}
                    <p>${escapeHtml(question.explanation)}</p>
                  </div>
                </details>
              `;
            })
            .join("")}
        </div>
      </section>
    </div>
  `;
}

