function renderPlanPage(course) {
  const stats = courseStats(course);
  const selectedPlan = planById(selectedPlanId);
  const price = planPrice(course, selectedPlan.id);
  const monthlyValue = planPrice(course, "monthly") * selectedPlan.months;
  const savings = Math.max(0, monthlyValue - price);
  const enrolled = isEnrolled(course.id);

  return marketingShell(
    "subscribe",
    `
      <main class="plan-page" style="--accent:${course.accent};--tint:${course.tint}">
        <div class="breadcrumb">
          <a href="#/subscribe">Plans &amp; access</a>
          ${icon("chevron")}
          <span>${escapeHtml(course.name)}</span>
        </div>

        <div class="plan-layout">
          <section>
            <div class="plan-course-head">
              <span class="plan-course-mark">${escapeHtml(course.short)}</span>
              <div>
                <p class="eyebrow">${escapeHtml(course.field)} · ${escapeHtml(course.level)}</p>
                <h1>${escapeHtml(course.name)}</h1>
              </div>
            </div>
            <p class="plan-course-lede">${escapeHtml(course.description)} Choose the access window that fits your study plan. Every option unlocks the same complete curriculum.</p>

            <div class="plan-stats">
              <div class="plan-stat"><strong>${stats.totalSections}</strong><span>Sections</span></div>
              <div class="plan-stat"><strong>${stats.totalQuestions}</strong><span>Questions</span></div>
              <div class="plan-stat"><strong>~${estimateStudyHours(course)}h</strong><span>Study time</span></div>
              <div class="plan-stat"><strong>Unlimited</strong><span>Retakes</span></div>
            </div>

            <div class="plan-includes">
              <h2>What your access includes</h2>
              <div class="plan-includes-list">
                <div class="plan-include">${icon("check")}<span>Every section in ${escapeHtml(course.name)}, including future question updates.</span></div>
                <div class="plan-include">${icon("check")}<span>Detailed explanations and correct-answer review for every question.</span></div>
                <div class="plan-include">${icon("check")}<span>Saved practice history with scores, timing, and best attempts.</span></div>
                <div class="plan-include">${icon("check")}<span>Unlimited retakes and pause-ready practice sessions.</span></div>
              </div>
            </div>

            <div class="plan-curriculum-preview">
              <h3>Curriculum overview</h3>
              ${course.categories
                .map((category) => {
                  const count = category.sections.reduce((sum, section) => sum + section.questions.length, 0);
                  return `
                    <div class="plan-curriculum-row">
                      <span><strong>${escapeHtml(category.name)}</strong> · ${category.sections.length} sections</span>
                      <span>${count} questions</span>
                    </div>
                  `;
                })
                .join("")}
            </div>
          </section>

          <aside class="checkout-card">
            <div class="checkout-head">
              <div>
                <h2>Course access</h2>
                <span>Choose a billing window</span>
              </div>
              ${enrolled ? `<span class="badge">${icon("check")} Active</span>` : `<span class="badge">${escapeHtml(course.short)}</span>`}
            </div>

            <div class="plan-options" role="radiogroup" aria-label="Billing period">
              ${PLAN_OPTIONS.map((plan) => {
                const planAmount = planPrice(course, plan.id);
                const planSave = planSavings(course, plan.id);
                return `
                  <button class="plan-option ${plan.id === selectedPlan.id ? "selected" : ""}" type="button" data-plan-option="${plan.id}" aria-pressed="${plan.id === selectedPlan.id}">
                    <span class="plan-radio"></span>
                    <span class="plan-option-copy">
                      <strong>${plan.name}</strong>
                      <span>${plan.blurb}</span>
                    </span>
                    <span class="plan-option-price">
                      <strong>$${planAmount}</strong>
                      <span>${planSave ? `Save $${planSave}` : plan.unit}</span>
                    </span>
                  </button>
                `;
              }).join("")}
            </div>

            <div class="checkout-summary">
              <div class="checkout-line"><span>${escapeHtml(course.name)} · ${selectedPlan.name}</span><strong>$${price}</strong></div>
              <div class="checkout-line"><span>Billing window</span><strong>${selectedPlan.unit}</strong></div>
              ${savings ? `<div class="checkout-line"><span>Savings vs monthly</span><strong>$${savings}</strong></div>` : ""}
              <div class="checkout-total"><span>Total today</span><strong>$${price}<small>.00</small></strong></div>
            </div>

            ${
              enrolled
                ? `<button class="btn btn-soft" type="button" disabled>${icon("check")} Access active</button>
                   <div class="checkout-signed"><span class="avatar">${icon("check")}</span><span>Your ${escapeHtml(course.short)} access is active in this workspace.</span></div>`
                : `<button class="btn btn-primary" type="button" data-plan-checkout="${course.id}">${icon("credit")} Get access ${icon("arrow-right")}</button>
                   ${
                     currentUser
                       ? `<div class="checkout-signed"><span class="avatar">${escapeHtml(initialsFor(currentUser.name))}</span><span>Continuing as ${escapeHtml(currentUser.email)}</span></div>`
                       : `<div class="checkout-signed"><span class="avatar">${icon("user")}</span><span>Demo checkout. No card is required.</span></div>`
                   }`
            }
            <p class="checkout-fine">${icon("lock")} This preview stores access locally in your browser. No payment details are collected.</p>
          </aside>
        </div>
      </main>
    `
  );
}

